-module(bmscl_guest_artifact).

-export([activate/2, artifact_path/2]).

-spec activate(file:filename_all(), binary()) -> ok | {error, term()}.
activate(Root0, DeploymentId) when is_binary(DeploymentId) ->
    case artifact_path(Root0, DeploymentId) of
        {error, PathReason} -> {error, PathReason};
        {ok, Path} ->
            %% Verify before activation so a package whose contents do not match
            %% the digest-derived directory can never become the active worker.
            %% activate_artifact/1 verifies again before code loading.
            case bmscl_artifact:verify(Path) of
                {error, VerifyReason} -> {error, {artifact_rejected, VerifyReason}};
                {ok, Spec} ->
                    ActualId = maps:get(deployment_id, Spec),
                    case ActualId =:= DeploymentId of
                        false -> {error, {artifact_digest_mismatch, DeploymentId, ActualId}};
                        true ->
                            case bmscl_deployment_manager:activate_artifact(Path) of
                                {ok, DeploymentId} -> ok;
                                {ok, OtherId} ->
                                    {error, {artifact_digest_mismatch, DeploymentId, OtherId}};
                                {error, ActivateReason} -> {error, ActivateReason}
                            end
                    end
            end
    end;
activate(_, _) ->
    {error, invalid_deployment_id}.

-spec artifact_path(file:filename_all(), binary()) -> {ok, file:filename()} | {error, term()}.
artifact_path(Root0, DeploymentId) when is_binary(DeploymentId) ->
    case {normalize_root(Root0), valid_deployment_id(DeploymentId)} of
        {{ok, Root}, true} ->
            {ok, filename:join(Root, binary_to_list(DeploymentId))};
        {{error, RootReason}, _} -> {error, RootReason};
        {_, false} -> {error, invalid_deployment_id}
    end;
artifact_path(_, _) ->
    {error, invalid_deployment_id}.

normalize_root(Root) when is_binary(Root) -> normalize_root(binary_to_list(Root));
normalize_root(Root) when is_list(Root), Root =/= [] ->
    case filename:pathtype(Root) of
        absolute -> {ok, filename:absname(Root)};
        _ -> {error, invalid_guest_artifact_root}
    end;
normalize_root(_) -> {error, invalid_guest_artifact_root}.

valid_deployment_id(Digest) when is_binary(Digest), byte_size(Digest) =:= 64 ->
    re:run(Digest, <<"^[0-9a-f]{64}$">>, [{capture, none}]) =:= match;
valid_deployment_id(_) -> false.

-module(bmscl_host_http).

-export([request/5]).

-define(MAX_URL_BYTES, 8192).
-define(MAX_HEADERS, 128).
-define(MAX_HEADER_NAME_BYTES, 128).
-define(MAX_HEADER_VALUE_BYTES, 8192).

-spec request(term(), binary(), binary(), list(), binary()) ->
    {ok, term()} | {error, binary()}.
request(Capability, Method, Url, Headers, Body)
  when is_binary(Method), is_binary(Url), is_list(Headers), is_binary(Body) ->
    case authorize(Capability) of
        {error, _} -> {error, <<"http_capability_denied">>};
        {ok, Meta} ->
            case broker_scope(<<"ctx.http">>) of
                {error, _} -> {error, <<"http_scope_unavailable">>};
                {ok, Scope} -> request_scoped(Method, Url, Headers, Body, Scope, Meta)
            end
    end;
request(_, _, _, _, _) ->
    {error, <<"http_request_invalid">>}.

authorize({http_capability, Token}) when is_binary(Token) ->
    bmscl_authority_broker:authorize(self(), <<"ctx.http">>, Token);
authorize(_) ->
    {error, invalid_capability_shape}.

broker_scope(Name) ->
    case bmscl_authority_broker:grant(self(), Name) of
        {ok, Grant} -> {ok, maps:get(<<"scope">>, Grant, undefined)};
        Error -> Error
    end.

request_scoped(Method, Url, Headers, Body, Scope, Meta) ->
    case validate_request(Method, Url, Headers, Body, Scope) of
        {error, Reason} -> {error, Reason};
        {ok, NormalizedHeaders} ->
            case application:get_env(bmscl_supervisor, http_provider_module, undefined) of
                undefined -> {error, <<"http_provider_unavailable">>};
                Provider when is_atom(Provider) ->
                    ProviderScope = harden_provider_scope(Scope),
                    try Provider:request(Method, Url, NormalizedHeaders, Body, ProviderScope, Meta) of
                        {ok, {response, Status, ResponseHeaders, ResponseBody}} = Ok
                          when is_integer(Status), Status >= 100, Status =< 599,
                               is_list(ResponseHeaders), is_binary(ResponseBody) ->
                            case byte_size(ResponseBody) =<
                                 maps:get(<<"max_response_body_bytes">>, Scope) of
                                true -> Ok;
                                false -> {error, <<"http_response_too_large">>}
                            end;
                        {error, Reason} when is_binary(Reason) -> {error, Reason};
                        _ -> {error, <<"http_provider_invalid_response">>}
                    catch
                        _:_ -> {error, <<"http_provider_failed">>}
                    end
            end
    end.

validate_request(Method, Url, Headers, Body, Scope) when is_map(Scope) ->
    case valid_security_scope(Scope) of
        false -> {error, <<"http_scope_insecure">>};
        true -> validate_request_secure(Method, Url, Headers, Body, Scope)
    end.

validate_request_secure(Method, Url, Headers, Body, Scope) ->
    Methods = maps:get(<<"methods">>, Scope, []),
    RequestMax = maps:get(<<"max_request_body_bytes">>, Scope, -1),
    case lists:member(Method, Methods) andalso allowed_method(Method) of
        false -> {error, <<"http_method_denied">>};
        true when byte_size(Body) > RequestMax -> {error, <<"http_request_too_large">>};
        true ->
            case allowed_url(Url, Scope) of
                false -> {error, <<"http_origin_denied">>};
                true -> normalize_headers(Headers)
            end
    end.

valid_security_scope(Scope) ->
    maps:get(<<"public_network_only">>, Scope, false) =:= true andalso
    maps:get(<<"max_redirects">>, Scope, -1) =:= 0.

harden_provider_scope(Scope) ->
    Scope#{
        <<"public_network_only">> => true,
        <<"deny_private_networks">> => true,
        <<"max_redirects">> => 0
    }.

allowed_method(<<"GET">>) -> true;
allowed_method(<<"HEAD">>) -> true;
allowed_method(<<"POST">>) -> true;
allowed_method(<<"PUT">>) -> true;
allowed_method(<<"PATCH">>) -> true;
allowed_method(<<"DELETE">>) -> true;
allowed_method(<<"OPTIONS">>) -> true;
allowed_method(_) -> false.

allowed_url(Url, Scope) when byte_size(Url) > 0, byte_size(Url) =< ?MAX_URL_BYTES ->
    case public_destination_literal(Url) of
        false -> false;
        true ->
            case canonical_origin(Url) of
                {ok, Origin} ->
                    AllowedOrigins = maps:get(<<"origins">>, Scope, []),
                    lists:any(fun(Allowed) ->
                        case canonical_origin(Allowed) of
                            {ok, Origin} -> true;
                            _ -> false
                        end
                    end, AllowedOrigins);
                _ -> false
            end
    end;
allowed_url(_, _) -> false.

public_destination_literal(Value) when is_binary(Value) ->
    try uri_string:parse(binary_to_list(Value)) of
        Parsed when is_map(Parsed) ->
            case maps:get(host, Parsed, undefined) of
                Host when is_list(Host), Host =/= [] -> public_host(Host);
                _ -> false
            end;
        _ -> false
    catch
        _:_ -> false
    end.

public_host(Host0) ->
    Host = strip_trailing_dot(string:lowercase(Host0)),
    case reserved_hostname(Host) of
        true -> false;
        false ->
            case inet:parse_address(Host) of
                {ok, Address} -> public_ip(Address);
                {error, _} -> true
            end
    end.

strip_trailing_dot([]) -> [];
strip_trailing_dot(Host) ->
    case lists:last(Host) of
        $. -> lists:sublist(Host, length(Host) - 1);
        _ -> Host
    end.

reserved_hostname("localhost") -> true;
reserved_hostname("metadata") -> true;
reserved_hostname("metadata.google.internal") -> true;
reserved_hostname("instance-data") -> true;
reserved_hostname(Host) ->
    lists:any(
      fun(Suffix) -> lists:suffix(Suffix, Host) end,
      [".localhost", ".local", ".internal", ".home.arpa"]).

public_ip({A, _, _, _}) when A =:= 0; A =:= 10; A =:= 127 -> false;
public_ip({100, B, _, _}) when B >= 64, B =< 127 -> false;
public_ip({169, 254, _, _}) -> false;
public_ip({172, B, _, _}) when B >= 16, B =< 31 -> false;
public_ip({192, 168, _, _}) -> false;
public_ip({198, B, _, _}) when B =:= 18; B =:= 19 -> false;
public_ip({A, _, _, _}) when A >= 224 -> false;
public_ip({_, _, _, _}) -> true;
public_ip({0, 0, 0, 0, 0, 0, 0, 0}) -> false;
public_ip({0, 0, 0, 0, 0, 0, 0, 1}) -> false;
public_ip({0, 0, 0, 0, 0, 16#ffff, G, H}) ->
    public_ip({G bsr 8, G band 16#ff, H bsr 8, H band 16#ff});
public_ip({A, _, _, _, _, _, _, _}) when (A band 16#fe00) =:= 16#fc00 -> false;
public_ip({A, _, _, _, _, _, _, _}) when (A band 16#ffc0) =:= 16#fe80 -> false;
public_ip({A, _, _, _, _, _, _, _}) when (A band 16#ff00) =:= 16#ff00 -> false;
public_ip({_, _, _, _, _, _, _, _}) -> true;
public_ip(_) -> false.

canonical_origin(Value) when is_binary(Value) ->
    try uri_string:parse(binary_to_list(Value)) of
        Parsed when is_map(Parsed) ->
            Scheme = maps:get(scheme, Parsed, undefined),
            Host = maps:get(host, Parsed, undefined),
            Port = maps:get(port, Parsed, 443),
            case Scheme =:= "https" andalso is_list(Host) andalso Host =/= [] andalso
                 is_integer(Port) andalso Port > 0 andalso Port =< 65535 andalso
                 not maps:is_key(userinfo, Parsed) of
                true ->
                    {ok, unicode:characters_to_binary(
                        io_lib:format("https://~s:~p", [string:lowercase(Host), Port]))};
                false -> error
            end;
        _ -> error
    catch
        _:_ -> error
    end.

normalize_headers(Headers) when length(Headers) =< ?MAX_HEADERS ->
    normalize_headers(Headers, []);
normalize_headers(_) -> {error, <<"http_headers_invalid">>}.

normalize_headers([], Acc) -> {ok, lists:reverse(Acc)};
normalize_headers([{Name, Value} | Rest], Acc)
  when is_binary(Name), is_binary(Value),
       byte_size(Name) > 0, byte_size(Name) =< ?MAX_HEADER_NAME_BYTES,
       byte_size(Value) =< ?MAX_HEADER_VALUE_BYTES ->
    case valid_header_name(Name) andalso valid_header_value(Value) andalso
         not forbidden_header(Name) of
        true -> normalize_headers(Rest, [{Name, Value} | Acc]);
        false -> {error, <<"http_header_denied">>}
    end;
normalize_headers(_, _) -> {error, <<"http_headers_invalid">>}.

valid_header_name(Name) ->
    lists:all(fun(Byte) ->
        (Byte >= $a andalso Byte =< $z) orelse
        (Byte >= $0 andalso Byte =< $9) orelse Byte =:= $-
    end, binary_to_list(Name)).

valid_header_value(Value) ->
    binary:match(Value, <<"\r">>) =:= nomatch andalso
    binary:match(Value, <<"\n">>) =:= nomatch andalso
    binary:match(Value, <<0>>) =:= nomatch.

forbidden_header(<<"host">>) -> true;
forbidden_header(<<"connection">>) -> true;
forbidden_header(<<"proxy-authorization">>) -> true;
forbidden_header(<<"proxy-authenticate">>) -> true;
forbidden_header(<<"transfer-encoding">>) -> true;
forbidden_header(<<"content-length">>) -> true;
forbidden_header(<<"upgrade">>) -> true;
forbidden_header(<<"te">>) -> true;
forbidden_header(_) -> false.

-module(bmscl_httpc_provider).

-export([request/6, public_address/1]).

-spec request(binary(), binary(), list(), binary(), map(), map()) ->
    {ok, term()} | {error, binary()}.
request(Method, Url, Headers, Body, Scope, Meta) ->
    case public_target(Url, Scope) of
        false -> {error, <<"http_public_network_required">>};
        true ->
            Timeout = remaining_timeout(Meta),
            case Timeout > 0 of
                false -> {error, <<"http_deadline_exceeded">>};
                true -> do_request(Method, Url, Headers, Body, Scope, Timeout)
            end
    end.

do_request(Method, Url, Headers, Body, Scope, Timeout) ->
    ResponseMax = maps:get(<<"max_response_body_bytes">>, Scope),
    HttpOptions = [
        {timeout, Timeout},
        {connect_timeout, erlang:min(5000, Timeout)},
        {autoredirect, false},
        {ssl, httpc:ssl_verify_host_options(true)},
        {max_header_size, 16384},
        {max_body_size, ResponseMax}
    ],
    Request = httpc_request(Method, Url, Headers, Body),
    case Request of
        error -> {error, <<"http_method_invalid">>};
        {MethodAtom, RequestTuple} ->
            %% The trusted manager owns the async request id and monitors this
            %% invocation. If the actor is killed for timeout/memory/mailbox or
            %% caller cancellation, it cancels httpc work instead of leaving a
            %% request/socket alive in a node-wide client pool.
            case bmscl_http_request_manager:request(
                   MethodAtom, RequestTuple, HttpOptions) of
                {ok, {{_Version, Status, _Reason}, ResponseHeaders0, ResponseBody}}
                  when is_integer(Status), is_binary(ResponseBody),
                       byte_size(ResponseBody) =< ResponseMax ->
                    case normalize_response_headers(ResponseHeaders0) of
                        {ok, ResponseHeaders} ->
                            {ok, {response, Status, ResponseHeaders, ResponseBody}};
                        error -> {error, <<"http_response_headers_invalid">>}
                    end;
                {ok, {{_Version, _Status, _Reason}, _Headers, BodyTooLarge}}
                  when is_binary(BodyTooLarge) ->
                    {error, <<"http_response_too_large">>};
                {error, http_request_capacity_exceeded} ->
                    {error, <<"http_capacity_exceeded">>};
                {error, _} -> {error, <<"http_request_failed">>};
                _ -> {error, <<"http_provider_invalid_response">>}
            end
    end.

httpc_request(<<"GET">>, Url, Headers, <<>>) -> {get, {to_list(Url), to_httpc_headers(Headers)}};
httpc_request(<<"HEAD">>, Url, Headers, <<>>) -> {head, {to_list(Url), to_httpc_headers(Headers)}};
httpc_request(<<"DELETE">>, Url, Headers, <<>>) -> {delete, {to_list(Url), to_httpc_headers(Headers)}};
httpc_request(<<"OPTIONS">>, Url, Headers, <<>>) -> {options, {to_list(Url), to_httpc_headers(Headers)}};
httpc_request(Method, Url, Headers, Body)
  when Method =:= <<"POST">>; Method =:= <<"PUT">>; Method =:= <<"PATCH">> ->
    {ContentType, Headers1} = take_content_type(Headers),
    Atom = case Method of
        <<"POST">> -> post;
        <<"PUT">> -> put;
        <<"PATCH">> -> patch
    end,
    {Atom, {to_list(Url), to_httpc_headers(Headers1), to_list(ContentType), Body}};
httpc_request(_, _, _, _) -> error.

take_content_type(Headers) ->
    case lists:keytake(<<"content-type">>, 1, Headers) of
        {value, {_, Value}, Rest} -> {Value, Rest};
        false -> {<<"application/octet-stream">>, Headers}
    end.

to_httpc_headers(Headers) ->
    [{to_list(Name), to_list(Value)} || {Name, Value} <- Headers].

normalize_response_headers(Headers) when is_list(Headers), length(Headers) =< 128 ->
    try
        {ok, [{lower_binary(Name), iolist_to_binary(Value)} || {Name, Value} <- Headers]}
    catch
        _:_ -> error
    end;
normalize_response_headers(_) -> error.

lower_binary(Value) ->
    unicode:characters_to_binary(string:lowercase(to_list(Value))).

to_list(Value) when is_binary(Value) -> unicode:characters_to_list(Value);
to_list(Value) when is_list(Value) -> Value.

remaining_timeout(Meta) ->
    Deadline = maps:get(<<"deadline_unix_ms">>, Meta, 0),
    erlang:min(30000, erlang:max(0, Deadline - erlang:system_time(millisecond))).

%% This DNS check is defense in depth. OTP httpc resolves the hostname again
%% when it opens the connection, so production must also enforce the same
%% private/link-local/metadata denial at the host or VM egress layer. That
%% outer rule is the non-bypassable boundary against DNS rebinding/TOCTOU.
public_target(Url, Scope) ->
    maps:get(<<"public_network_only">>, Scope, false) =:= true andalso
    case target_host(Url) of
        {ok, Host} ->
            case resolve_addresses(Host) of
                [] -> false;
                Addresses -> lists:all(fun public_address/1, Addresses)
            end;
        error -> false
    end.

target_host(Url) ->
    try uri_string:parse(to_list(Url)) of
        #{scheme := "https", host := Host} when is_list(Host), Host =/= [] -> {ok, Host};
        _ -> error
    catch
        _:_ -> error
    end.

resolve_addresses(Host) ->
    V4 = case inet:getaddrs(Host, inet) of {ok, A4} -> A4; _ -> [] end,
    V6 = case inet:getaddrs(Host, inet6) of {ok, A6} -> A6; _ -> [] end,
    lists:usort(V4 ++ V6).

%% IPv4: reject non-global ranges that can expose host, metadata, service,
%% benchmark, documentation or reserved networks.
public_address({A, _, _, _}) when A =:= 0; A =:= 10; A =:= 127 -> false;
public_address({100, B, _, _}) when B >= 64, B =< 127 -> false;
public_address({169, 254, _, _}) -> false;
public_address({172, B, _, _}) when B >= 16, B =< 31 -> false;
public_address({192, 0, 0, _}) -> false;
public_address({192, 0, 2, _}) -> false;
public_address({192, 168, _, _}) -> false;
public_address({198, B, _, _}) when B =:= 18; B =:= 19 -> false;
public_address({198, 51, 100, _}) -> false;
public_address({203, 0, 113, _}) -> false;
public_address({A, _, _, _}) when A >= 224 -> false;
public_address({_, _, _, _}) -> true;

%% IPv4-mapped IPv6 must inherit the IPv4 policy. Without this normalization a
%% mapped loopback/link-local/private address would otherwise match the generic
%% IPv6 allow clause below.
public_address({0,0,0,0,0,16#ffff,A,B}) ->
    public_address(ipv4_from_words(A, B));
%% Deprecated IPv4-compatible IPv6 has surprising routing semantics; reject it
%% rather than creating a second representation for an IPv4 destination.
public_address({0,0,0,0,0,0,A,B}) when A =/= 0; B > 1 -> false;
%% Translation/tunneling mechanisms can encode another address family and make
%% an apparently public IPv6 literal reach an IPv4 target after this check.
public_address({16#0064,16#ff9b,0,0,0,0,_,_}) -> false; %% NAT64 WKP
public_address({16#2002,_,_,_,_,_,_,_}) -> false;       %% 6to4
public_address({16#2001,0,_,_,_,_,_,_}) -> false;       %% Teredo

public_address({0,0,0,0,0,0,0,0}) -> false;
public_address({0,0,0,0,0,0,0,1}) -> false;
public_address({A, _, _, _, _, _, _, _}) when (A band 16#fe00) =:= 16#fc00 -> false;
public_address({A, _, _, _, _, _, _, _}) when (A band 16#ffc0) =:= 16#fe80 -> false;
public_address({A, _, _, _, _, _, _, _}) when (A band 16#ff00) =:= 16#ff00 -> false;
public_address({16#2001,16#0db8,_,_,_,_,_,_}) -> false;
public_address({_, _, _, _, _, _, _, _}) -> true;
public_address(_) -> false.

ipv4_from_words(A, B) when A >= 0, A =< 16#ffff, B >= 0, B =< 16#ffff ->
    {A bsr 8, A band 16#ff, B bsr 8, B band 16#ff}.
